void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;

    // Scale coordinate space (from 0 to 4)
    uv *= 4.0;

    // Scroll the pattern over time
    uv.y += iTime * 0.2;

    // Create the checkered pattern
    // Floor to only increase by discrete values
    // Mod to get a value between 0 and 2 for every coordinate
    float checker = mod(floor(uv.x) + floor(uv.y), 2.0);

    // Anything above 1 is black, anything below 1 is white
    vec3 col = vec3(step(1.0, checker));

    // Output to screen
    fragColor = vec4(col, 1.0);
}
